@startuml

class Location {
  + Address : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : int
}

class Car {
  + Seats : int
}

class Van {}

class Driver {
  + FirstName : string
  + LastName : string
}

class Order {
  + OriginLocation : Location
  + DestinationLocation : Location
  + AssignedDriver : Driver
  + ExecutionDate : date
}

Vehicle "1" -- "*" Driver : drivenBy
Order "0..*" -- "1" Driver : carriedOutBy

@enduml

